let serial=0;
export function studioArt(kind,label='Minh họa khoa học'){const id=`studio-art-${++serial}`,g=id+'-g',h=id+'-h';return `<svg viewBox="0 0 720 410" role="img" aria-label="${label}"><defs><linearGradient id="${g}" x2="1" y2="1"><stop stop-color="#c7d7a0"/><stop offset="1" stop-color="#688e5d"/></linearGradient><radialGradient id="${h}"><stop stop-color="#9cc6b1" stop-opacity=".75"/><stop offset="1" stop-color="#9cc6b1" stop-opacity="0"/></radialGradient></defs>${(shapes[kind]||shapes.leaf).replaceAll('url(#G)',`url(#${g})`).replaceAll('url(#H)',`url(#${h})`)}</svg>`}
export function immuneArt({step=0,unit='',unitId='',virus=false,complete=false}={}){
 const agentX=unitId==='cytotoxic'?470:205;
 const agentShape=unitId==='dendritic'?'<path d="m-13-45-24-35-7 39-39-5 24 29-23 28 40-4 7 33 25-23 31 20-3-38 28-15-31-20 11-36-31 11Z" fill="#99baa4" stroke="#638870" stroke-width="3"/>':`<ellipse rx="${unitId==='plasma'?70:57}" ry="${unitId==='plasma'?55:61}" fill="${unitId==='cytotoxic'?'#c7b494':'#a2bea6'}" stroke="#638870" stroke-width="3"/>`;
 const antibodies=Array.from({length:8},(_,i)=>`<path class="immune-antibody" d="m${305+i*22} ${110+i%3*37}v-17m0 0-9-10m9 10 9-10" fill="none" stroke="#528a84" stroke-width="3"/>`).join('');
 return `<svg viewBox="0 0 800 390" role="img" aria-label="${unit||'Tương tác miễn dịch'}: hình minh họa, màu sắc quy ước"><defs><radialGradient id="immune-glow"><stop stop-color="#e1e9c7"/><stop offset="1" stop-color="#b4cba5"/></radialGradient></defs><path d="M0 45q220 50 400 0t400 0M0 330q220-50 400 0t400 0" stroke="#b5c7a6" fill="none" stroke-width="28" opacity=".4"/><g class="immune-host ${unitId==='cytotoxic'?'immune-apoptosis':''}"><path d="M540 95q97-38 152 46t-27 142-128-12-53-93 56-83" fill="url(#immune-glow)" stroke="#94ad88" stroke-width="3"/><ellipse cx="599" cy="189" rx="43" ry="36" fill="#b3aabd"/>${virus&&!complete?Array.from({length:5},(_,i)=>`<circle cx="${543+i*20}" cy="${218+i%2*20}" r="6" fill="#bd8d73"/>`).join(''):''}${virus?'<path d="m494 170 18 0 0 16-18 0m17-8 12-8" fill="none" stroke="#857b9b" stroke-width="4"/>':''}</g><g class="immune-agent" transform="translate(${agentX} 187)">${agentShape}<ellipse cx="-10" cy="1" rx="26" ry="32" fill="#829c8e"/>${unitId==='macrophage'?'<circle cx="28" cy="8" r="18" fill="#d9dfb9" stroke="#8ca177"/><rect x="19" y="4" width="18" height="9" rx="4" fill="#b69b6c"/>':''}${unitId==='bcell'||unitId==='plasma'?'<path d="M-43 8q40-42 80 5m-70 8q32-29 57 4m-55 8q25-20 50 3" fill="none" stroke="#d5dfbd" stroke-width="3"/>':''}</g>${complete?'<g fill="#a4bf9d" stroke="#688f6e"><circle cx="302" cy="178" r="24"/><circle cx="348" cy="222" r="19"/><circle cx="337" cy="133" r="18"/></g>':unitId==='helper'||unitId==='dendritic'?'<g><circle cx="333" cy="185" r="47" fill="#d2c396" stroke="#a89c74" stroke-width="3"/><circle cx="329" cy="185" r="24" fill="#b2a98a"/><path d="m267 169 22 15-22 16m20-15h7" stroke="#748b79" fill="none" stroke-width="4"/></g>':unitId==='bcell'?'<g fill="#abc59d" stroke="#75996c"><circle cx="321" cy="136" r="25"/><circle cx="334" cy="216" r="25"/><circle cx="382" cy="175" r="25"/></g>':Array.from({length:unitId==='macrophage'?3:5},(_,i)=>`<g class="immune-pathogen" style="--i:${i}" transform="translate(${320+i%3*48} ${95+Math.floor(i/3)*153}) rotate(${i*37})">${virus?'<circle r="13" fill="#c7a582" stroke="#a9836b" stroke-width="3"/><path d="M-22 0h44M0-22v44M-15-15l30 30m0-30-30 30" stroke="#a9836b" stroke-width="3"/>':'<rect x="-16" y="-8" width="32" height="16" rx="8" fill="#c5ac78" stroke="#a58d63" stroke-width="2"/>'}</g>`).join('')}${unitId==='plasma'?antibodies:''}<text x="${agentX}" y="310" text-anchor="middle" font-size="16" fill="#355741">${unit||'Tế bào miễn dịch'}</text><text x="615" y="320" text-anchor="middle" font-size="15" fill="#48674c">${virus?'Tế bào nhiễm virus':'Mô cơ thể'}</text>${unitId==='dendritic'||unitId==='helper'?'<text x="333" y="270" text-anchor="middle" font-size="13" fill="#586c4c">Tín hiệu đặc hiệu</text>':''}${unitId==='cytotoxic'?'<text x="600" y="75" text-anchor="middle" font-size="13" fill="#78684c">Kích hoạt chết theo chương trình</text>':''}<text x="400" y="375" text-anchor="middle" font-size="12" fill="#536b50">Sơ đồ minh họa · Không theo tỉ lệ · Các quá trình có thể chồng lấp</text></svg>`;
}
